        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Yahut, göklerin, yerin ve ikisi arasında bulunanların hükümranlığı onların elinde midir? Öyle ise sebeplere tevessül edip göğe yükselsinler"
        }
